package com.trough.hot;
import android.os.*;import java.io.*;import org.json.*;
final class HalfSwordSwingCheck implements Runnable {
 final HalfSwordView v;final HalfSwordAimCheck input;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();int stage,steps;double x,y,z,peak,returned;JSONArray player;boolean complete,pausedSingle,duplicateIgnored;
 HalfSwordSwingCheck(HalfSwordView view){v=view;input=new HalfSwordAimCheck(v);}void start(){ui.postDelayed(this,150);}void need(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}
 double motion(){return Math.sqrt(Math.pow(v.opponentHandX-x,2)+Math.pow(v.opponentHandY-y,2)+Math.pow(v.opponentHandZ-z,2));}
 public void run(){try{need(SystemClock.uptimeMillis()-began<25000,"Swing timeout");need(v.renderVisible&&!v.characterFailed,"Scene unavailable");if(stage>=4&&stage<=7)peak=Math.max(peak,motion());switch(stage){
 case 0:if(v.characterRunning)input.click("Run / pause");if(v.opponentFollow)input.click("Opponent spacing · prototype");input.click("Reset physics");input.click("Stance support setup");stage=1;break;
 case 1:if(v.resetPending())break;input.click("Run / pause");steps=v.characterSteps;stage=2;break;
 case 2:if(v.characterSteps-steps<60)break;player=input.observation().getJSONArray("right_hand_cm");x=v.opponentHandX;y=v.opponentHandY;z=v.opponentHandZ;input.click("Run / pause");input.pausedSteps=-1;stage=3;break;
 case 3:if(!input.pausedScene(false))break;steps=v.characterSteps;input.click("Opponent swing");stage=4;break;
 case 4:if(v.characterBusy||!v.opponentSwingActive)break;need(!v.characterRunning&&v.characterSteps==steps+1&&v.opponentSwingStarts==1,"Swing auto-ran or failed");pausedSingle=true;input.click("Opponent swing");steps=v.characterSteps;stage=5;break;
 case 5:if(v.characterBusy||v.characterSteps<steps+1)break;need(v.opponentSwingStarts==1&&!v.characterRunning,"Duplicate queued swing");duplicateIgnored=true;input.click("Run / pause");steps=v.characterSteps;stage=6;break;
 case 6:if(v.characterSteps-steps<30)break;input.observation();input.click("Run / pause");input.pausedSteps=-1;stage=7;break;
 case 7:if(!input.pausedScene(true))break;{File base=new File(v.getContext().getFilesDir(),"home/.trough");try(FileInputStream in=new FileInputStream(new File(base,"half-sword-aim-held.png"));FileOutputStream out=new FileOutputStream(new File(base,"half-sword-opponent-swing.png"))){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}}input.click("Run / pause");steps=v.characterSteps;stage=8;break;
 case 8:peak=Math.max(peak,motion());if(v.characterSteps-steps<210)break;returned=motion();need(!v.opponentSwingActive&&v.opponentSwingStarts==1&&peak>10&&returned<8,"Physical swing/neutral return failed");need(v.opponentBladeAvailable&&v.opponentBladeProbes>200,"Secondary blade query inactive");{JSONArray current=input.observation().getJSONArray("right_hand_cm");double d=0;for(int k=0;k<3;k++)d+=Math.pow(current.getDouble(k)-player.getDouble(k),2);need(Math.sqrt(d)<8,"Opponent swing changed player hand");}input.click("Run / pause");input.pausedSteps=-1;stage=9;break;
 case 9:if(!input.pausedScene(false))break;complete=true;finish(null);return;
 }ui.postDelayed(this,50);}catch(Throwable e){v.characterRunning=false;v.cancelAllTouchInputs();v.refreshRunControl();finish(e.toString());}}
 void finish(String error){try{JSONObject o=new JSONObject().put("passed",complete&&error==null).put("error",error==null?"":error).put("stage",stage).put("paused_single_step",pausedSingle).put("duplicate_ignored",duplicateIgnored).put("peak_hand_motion_cm",peak).put("neutral_return_cm",returned).put("blade_queries",v.opponentBladeProbes).put("blade_contacts",v.opponentBladeContacts).put("steps",v.characterSteps).put("module",HalfSwordBridge.loadedModuleSha256).put("performance",v.performance()).put("time_ms",System.currentTimeMillis()).put("scope","Explicit physical opponent gesture and query only; no hit response/damage/fighting AI");Payloads.writeSmall(new File(v.getContext().getFilesDir(),"home/.trough/half-sword-swing-check-result.json"),o.toString());}catch(Exception ignored){}}
}
